import './navigation.mjs';
import {createWorld} from './home-behavior.mjs';
const manifest=await(await fetch('home-tatari.json')).json(),field=document.getElementById('field'),mobile=matchMedia('(max-width:900px)');
let world,frame=0,last=0;
const paused=()=>false;
function fallbackToImage(c){c.fallback=true;c.renderedToken=-1;c.ready=false;render(c)}

function populate(){field.replaceChildren();const count=mobile.matches?1+Math.floor(Math.random()*2):3+Math.floor(Math.random()*3);world=createWorld(manifest.characters,{count});for(const [i,c] of world.walkers.entries()){const wrapper=document.createElement('div');wrapper.className='tatari';wrapper.dataset.name=c.name;wrapper.dataset.tier='1';wrapper.dataset.appearance=c.variant;wrapper.setAttribute('aria-hidden','true');wrapper.style.bottom=(i%3*2)+'%';const video=document.createElement('video');video.muted=true;video.autoplay=true;video.playsInline=true;video.preload='none';video.disablePictureInPicture=true;video.setAttribute('muted','');video.setAttribute('playsinline','');const fallback=document.createElement('img');fallback.alt='';fallback.draggable=false;fallback.hidden=true;wrapper.append(video,fallback);field.append(wrapper);c.node=wrapper;c.video=video;c.image=fallback;c.renderedToken=-1;c.fallback=!video.canPlayType('video/webm; codecs="vp9"')||/iPad|iPhone|iPod/.test(navigator.userAgent);video.onended=()=>{if(c.action==='Disable'){video.pause();return}world.loopEnded(c);if(c.loops>0&&c.renderedToken===c.token){video.currentTime=0;video.play().catch(()=>{})}};video.oncanplay=()=>{c.ready=true;if(document.hidden||paused())video.pause();else video.play().catch(()=>fallbackToImage(c))};video.onerror=()=>fallbackToImage(c);fallback.onload=()=>{c.ready=true};render(c)}start()}
function render(c){const clip=manifest.characters[c.name][c.variant][c.action];if(c.renderedToken!==c.token){c.renderedToken=c.token;c.node.dataset.action=c.action;if(c.fallback){c.video.pause();c.video.hidden=true;c.image.hidden=false;c.image.src=clip.webp}else{c.image.hidden=true;c.video.hidden=false;c.video.loop=c.action==='Move';c.video.src=clip.webm;c.video.load();const token=c.token;setTimeout(()=>{if(c.token===token&&!c.fallback&&c.video.readyState<2)fallbackToImage(c)},8000)}}const size=c.node.getBoundingClientRect().width,travel=Math.max(0,field.clientWidth-size);c.node.style.left=c.x*travel+'px';c.node.style.transform='scaleX('+c.dir+')';c.node.style.zIndex=String(Math.round(c.node.getBoundingClientRect().bottom))}
function animate(now){frame=0;if(document.hidden||paused())return;const dt=last?Math.min((now-last)/1000,.05):0;last=now;world.tick(dt);world.walkers.forEach(render);frame=requestAnimationFrame(animate)}
function start(){cancelAnimationFrame(frame);last=0;for(const c of world?.walkers||[]){if(document.hidden||paused())c.video.pause();else if(!c.fallback)c.video.play().catch(()=>fallbackToImage(c))}if(!document.hidden&&!paused())frame=requestAnimationFrame(animate)}
mobile.addEventListener('change',populate);document.addEventListener('visibilitychange',start);new ResizeObserver(()=>world?.walkers.forEach(render)).observe(field);populate();
